package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.learning.courseprogressshare.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class CourseProgressShareStoreIntegrationTest {
 CourseProgressStoreIntegrationTest f;CourseProgressShareStore store;CourseContextClient.Sharing a;
 @BeforeEach void setup(){f=new CourseProgressStoreIntegrationTest();f.setup();store=new CourseProgressShareStore(f.source,f.store,Clock.systemUTC());a=new CourseContextClient.Sharing(f.ref,1,true,"OWNER",1,List.of());}
 CourseProgressShareStore.Share share(long expected,long progress){return store.change(a,expected,"SHARED",progress,f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){f.status(code,op);}
 CourseContextClient.Sharing authority(long policy,boolean enabled,long member,long enrollment,String role){return new CourseContextClient.Sharing(f.context(f.ref.principalId(),role,"ACTIVE","ENROLLED",enrollment,3),policy,enabled,"OWNER",member,List.of());}
 CourseContextClient.Sharing owner(long membership,long enrollment){return new CourseContextClient.Sharing(f.context(f.ids.next(),"OWNER","ACTIVE","NOT_ENROLLED",0,3),1,true,"OWNER",1,List.of(new CourseContextClient.Eligible(f.ref.principalId(),membership,f.ref.enrollmentId(),enrollment)));}
 @Test void privateProgressDoesNotImplicitlyPublishAndInitialWithdrawIsNoOp(){f.change(0,0,"COMPLETED");assertNull(store.get(a).share());assertEquals(1,store.get(a).preview().completedStudies());assertNull(store.change(a,0,"WITHDRAWN",0,f.trace));assertTrue(store.history(a,Long.MAX_VALUE,5).items().isEmpty());}
 @Test void explicitSummaryContainsCountsWithoutStudyStepsAndIndependentAudit()throws Exception{f.change(0,0,"COMPLETED");var v=share(0,1);assertEquals(7,v.shareId().version());assertTrue(store.get(a).effectiveShared());assertEquals(1,v.completedStudies());assertEquals(2,v.totalStudies());assertEquals(v,store.history(a,Long.MAX_VALUE,5).items().getFirst().snapshot());var e=CourseProgressShareEnvelopeV1.parseFrom(f.sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.shareId()));var p=CourseProgressShareSnapshotV1.parseFrom(e.getPayload());assertEquals("OWNER",p.getAudience());assertEquals(1,p.getProgressVersion());assertEquals(f.trace,e.getTraceId());assertEquals("CourseProgressShare",e.getAggregateType());assertFalse(p.getAllFields().keySet().stream().anyMatch(k->k.getName().contains("steps")));assertEquals("PARTICIPANT_ONLY",f.store.get(f.ref).audience());}
 @Test void laterPrivateProgressNeverChangesSharedSnapshot(){f.change(0,0,"COMPLETED");var v=share(0,1);f.change(1,1,"COMPLETED");assertEquals(v,store.get(a).share());assertEquals(2,store.get(a).preview().completedStudies());assertEquals(1,store.history(a,Long.MAX_VALUE,5).items().size());var next=share(1,2);assertEquals(v.shareId(),next.shareId());assertEquals(2,next.completedStudies());assertEquals(next,share(2,2));status(412,()->share(1,2));}
 @Test void stalePreviewPolicyRoleOrNoSavedProgressCannotPublish(){status(409,()->share(0,0));f.change(0,0,"COMPLETED");status(409,()->share(0,2));status(409,()->store.change(authority(2,false,1,1,"MEMBER"),0,"SHARED",1,f.trace));status(409,()->store.change(authority(1,true,1,1,"VIEWER"),0,"SHARED",1,f.trace));assertNull(store.get(a).share());}
 @Test void policyMembershipAndEnrollmentEpochsHideUntilReconsent(){f.change(0,0,"COMPLETED");var v=share(0,1);for(var changed:List.of(authority(2,false,1,1,"MEMBER"),authority(3,true,1,1,"MEMBER"),authority(1,true,3,1,"MEMBER"),authority(1,true,1,3,"MEMBER"))){assertFalse(store.get(changed).effectiveShared());}a=authority(3,true,3,3,"MEMBER");var republished=share(1,1);assertTrue(store.get(a).effectiveShared());assertEquals(v.shareId(),republished.shareId());assertEquals(3,republished.policyVersion());}
 @Test void withdrawalAllowedAfterPolicyOffViewerAndCourseRetirement(){f.change(0,0,"COMPLETED");share(0,1);var disabled=new CourseContextClient.Sharing(f.context(f.ref.principalId(),"VIEWER","RETIRED","WITHDRAWN",2,4),2,false,"OWNER",2,List.of());var withdrawn=store.change(disabled,1,"WITHDRAWN",0,f.trace);assertEquals("WITHDRAWN",withdrawn.state());assertEquals(withdrawn,store.change(disabled,2,"WITHDRAWN",0,f.trace));assertFalse(store.get(a).effectiveShared());assertEquals(1,f.store.get(f.ref).version());}
 @Test void ownerOnlyReceivesCurrentlyEligibleMinimalSummary(){f.change(0,0,"COMPLETED");var v=share(0,1);var o=owner(1,1);var scan=store.scan(o,null,20);var page=CourseProgressShareStore.filter(scan,o);assertEquals(v.shareId(),page.items().getFirst().shareId());assertEquals(1,page.items().getFirst().completedStudies());assertTrue(CourseProgressShareStore.filter(scan,owner(3,1)).items().isEmpty());assertTrue(CourseProgressShareStore.filter(scan,owner(1,3)).items().isEmpty());var noMember=new CourseContextClient.Sharing(o.learning(),1,true,"OWNER",1,List.of());assertTrue(CourseProgressShareStore.filter(scan,noMember).items().isEmpty());status(403,()->store.scan(a,null,20));assertNull(store.get(o).share());assertTrue(store.history(o,Long.MAX_VALUE,5).items().isEmpty());}
 @Test void duplicateConcurrentConsentHasOneWinner()throws Exception{f.change(0,0,"COMPLETED");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var tasks=new ArrayList<Future<Boolean>>();for(int n=0;n<4;n++)tasks.add(pool.submit(()->{try{share(0,1);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));int won=0;for(var t:tasks)if(t.get(20,TimeUnit.SECONDS))won++;assertEquals(1,won);assertEquals(1,store.history(a,Long.MAX_VALUE,5).items().size());}}
 @Test void outboxFailureRollsBackPublicationAndRevision(){f.change(0,0,"COMPLETED");String name="share_fail_"+f.ref.courseId().toString().replace("-","");String check=" CHECK(aggregatetype<>'course-progress-share' OR trace_id<>'"+f.trace+"') NOT VALID";f.sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->share(0,1));assertNull(store.get(a).share());assertTrue(store.history(a,Long.MAX_VALUE,5).items().isEmpty());}finally{f.sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var saved=share(0,1);f.sql.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->store.change(a,1,"WITHDRAWN",0,f.trace));assertEquals(saved,store.get(a).share());assertEquals(1,store.history(a,Long.MAX_VALUE,5).items().size());}finally{f.sql.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
 @Test void filteredEmptyPageKeepsScannedCursorWithoutLeakingParticipant(){f.change(0,0,"COMPLETED");share(0,1);var other=f.context(f.ids.next(),"MEMBER","ACTIVE","ENROLLED",1,3);f.store.change(other,other.studies().getFirst().studyId(),0,"IN_PROGRESS",f.trace);store.change(new CourseContextClient.Sharing(other,1,true,"OWNER",1,List.of()),0,"SHARED",1,f.trace);var o=owner(99,99);var first=store.scan(o,null,1);assertNotNull(first.nextAfter());var hidden=CourseProgressShareStore.filter(first,new CourseContextClient.Sharing(o.learning(),1,true,"OWNER",1,List.of()));assertTrue(hidden.items().isEmpty());assertEquals(first.nextAfter(),hidden.nextAfter());var next=store.scan(o,hidden.nextAfter(),1);assertEquals(1,next.items().size());assertNull(next.nextAfter());assertNotEquals(first.items().getFirst().shareId(),next.items().getFirst().shareId());}
}
